/* teste do desafio o-inventario-final — counter_protocol (03-tdd 3.9.3).
   Canal RETORNO: o teste chama as funcoes do aluno por prototipo e confere o
   que elas devolvem. Um cenario abre o proprio inventario.txt para provar que
   o cadastro esta no DISCO, e nao na memoria do programa. */

/* prototipos das funcoes do aluno */
void zerarInventario(void);
void adicionarItem(char nome[], double preco);
double totalDoInventario(void);
void itemMaisCaro(char destino[]);

SM_TEST(o_caderno_zerado_e_o_item_gravado) {
    zerarInventario();
    checa_double("o caderno zerado soma zero", totalDoInventario(), 0.0,
                 "sem nenhum item gravado, o total do inventario e zero");
    adicionarItem("martelo", 25.50);

    FILE *f = fopen("inventario.txt", "r");
    char linha[80] = "(nada gravado)";
    fgets(linha, 80, f);
    checa_str("a linha gravada no caderno", linha, "martelo 25.50\n",
              "cada item entra no arquivo como nome e preco, na mesma linha");
    char fim[80] = "(nao ha linha a mais)";
    fgets(fim, 80, f);
    checa_str("um item, uma linha", fim, "(nao ha linha a mais)",
              "um item gravado ocupa exatamente uma linha do caderno");
    fclose(f);
}

SM_TEST(o_total_le_o_caderno_do_disco) {
    /* o teste escreve o caderno: a soma tem de sair do ARQUIVO */
    zerarInventario();
    FILE *g = fopen("inventario.txt", "w");
