#include <stdio.h>
#include <string.h>

void zerarInventario(void) {
    FILE *f = fopen("inventario.txt", "w");
    if (f == NULL) {
        return;
    }
    fclose(f);
}

void adicionarItem(char nome[], double preco) {
    FILE *f = fopen("inventario.txt", "a");
    if (f == NULL) {
        return;
    }
    fprintf(f, "%s %.2f\n", nome, preco);
    fclose(f);
}

double totalDoInventario(void) {
    char nome[40];
    double preco;
    double soma = 0;
    FILE *f = fopen("inventario.txt", "r");
    if (f == NULL) {
        return 0;
    }
    while (fscanf(f, "%39s %lf", nome, &preco) == 2) {
        soma += preco;
    }
    fclose(f);
    return soma;
}

void itemMaisCaro(char destino[]) {
    char nome[40];
    double preco;
    double maior = 0;
    FILE *f = fopen("inventario.txt", "r");
    if (f == NULL) {
        return;
    }
    while (fscanf(f, "%39s %lf", nome, &preco) == 2) {
        if (maior < preco) {
            maior = preco;
            strncpy(destino, nome, 40);
        }
    }
    fclose(f);
}
